package net.famzangl.minecraft.aimbow.aiming;
import net.minecraft.client.Minecraft;
import net.minecraft.entity.Entity;
import net.minecraft.init.Blocks;
import net.minecraft.util.BlockPos;
import net.minecraft.util.MathHelper;
import net.minecraft.util.Vec3;
public final class TargetSimulator {private TargetSimulator(){} public static Vec3 simulateJump(Entity t,int ticks){double x=t.posX,y=t.posY,z=t.posZ,mx=t.motionX,my=t.motionY,mz=t.motionZ;for(int i=0;i<ticks;i++){x+=mx;y+=my;z+=mz;mx*=.98;my=(my-.08)*.98;mz*=.98;}return new Vec3(x,y,z);}public static Vec3 simulateVector(Entity t,int ticks){return new Vec3(t.posX+t.motionX*ticks,t.posY+t.motionY*ticks,t.posZ+t.motionZ*ticks);}public static Vec3 simulatePath(Entity t,int ticks){Minecraft mc=Minecraft.getMinecraft();if(mc.theWorld==null)return new Vec3(t.posX,t.posY,t.posZ);double x=t.posX,z=t.posZ;float yaw=t.rotationYaw*.017453292F;double dx=-MathHelper.sin(yaw)*.2,dz=MathHelper.cos(yaw)*.2;for(int i=0;i<ticks;i++){BlockPos next=new BlockPos(x+dx,t.posY-1,z+dz);if(mc.theWorld.getBlockState(next).getBlock()==Blocks.air){double oldDx=dx,oldDz=dz;BlockPos left=new BlockPos(x-oldDz*.5,t.posY-1,z+oldDx*.5),right=new BlockPos(x+oldDz*.5,t.posY-1,z-oldDx*.5);if(mc.theWorld.getBlockState(left).getBlock()!=Blocks.air){dx=-oldDz*.5;dz=oldDx*.5;}else if(mc.theWorld.getBlockState(right).getBlock()!=Blocks.air){dx=oldDz*.5;dz=-oldDx*.5;}else break;}x+=dx;z+=dz;}return new Vec3(x,t.posY,z);}public static boolean isBridge(Entity t){Minecraft mc=Minecraft.getMinecraft();if(mc.theWorld==null)return false;BlockPos below=new BlockPos(t.posX,t.posY-1,t.posZ);if(mc.theWorld.getBlockState(below).getBlock()==Blocks.air)return false;int solid=0;for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)if(mc.theWorld.getBlockState(below.add(x,0,z)).getBlock()!=Blocks.air)solid++;return solid<=3;}}
